fn double_halves(v: &mut Vec<i32>) {
    let mid = v.len() / 2;
    let left = &mut v[..mid];
    let right = &mut v[mid..];
    for x in left.iter_mut() { *x *= 2; }
    for x in right.iter_mut() { *x *= 2; }
}

fn main() {
    let mut v = vec![1, 2, 3, 4, 5, 6];
    double_halves(&mut v);
    println!("{:?}", v);
}
